contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        require(amount > 0);
        address pair = c.pairAddress();
        // ensure 'to' is not whitelisted via the only-Caller setter attempt
        // (cfo is unset so setWhite reverts; instead just choose a fresh address 'to',
        //  which is never whitelisted in a fresh deployment except liquidityReceiveAddress)
        bool reverted;
        try c.transferFrom(pair, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted || c.whiteCheck(pair, to));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        require(to != c.pairAddress());
        require(amount > 0);
        require(amount <= c.balanceOf(address(this)));
        c.setWhite(address(this), true);
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 pairBefore = c.balanceOf(c.pairAddress());
        uint256 contractBefore = c.balanceOf(address(c));
        c.transfer(c.pairAddress(), amount);
        assert(
            c.balanceOf(address(this)) == senderBefore - amount &&
            c.balanceOf(c.pairAddress()) == pairBefore + amount &&
            c.balanceOf(address(c)) == contractBefore
        );
    }
    receive() external payable {}
}

