    constructor(C _c) { c = _c; }
    function run(address spender, uint256 amount, uint256 decrease) public {
        require(spender != address(0));
        require(decrease <= amount);
        c.approve(spender, amount);
        uint256 afterApprove = c.allowance(address(this), spender);
        c.decreaseAllowance(spender, decrease);
        uint256 afterDecrease = c.allowance(address(this), spender);
        assert(
            afterApprove == amount &&
            afterDecrease == amount - decrease
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address victim) public payable {
        require(victim != address(0));

        // Before a caller is set, admin functions must revert.
        bool onlyCallerReverted;
        try c.setBlack(victim, true) { onlyCallerReverted = false; }
        catch { onlyCallerReverted = true; }

        // Set this test contract as the cfo, then blacklist the victim.
        c.setCaller(address(this));

        bool blackSet;
        try c.setBlack(victim, true) { blackSet = true; }
        catch { blackSet = false; }

        // Transfer to a blacklisted address must revert, even with amount 0.
        bool blackTransferReverted;
        try c.transfer(victim, 0) { blackTransferReverted = false; }
        catch { blackTransferReverted = true; }

        // Un-blacklisting restores the ability to transfer to the address.
        c.setBlack(victim, false);
        c.transfer(victim, 0);

        assert(onlyCallerReverted && blackSet && blackTransferReverted && c.balanceOf(victim) == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint amount) public payable {
        require(to != address(0));
        require(to != c.pairAddress());
        require(to != address(c));

        // Configure the test contract as the only caller, then whitelist both
        // endpoints of the transfer (the test contract is also the initial
        // token holder, having received the full minted supply).
        c.setCaller(address(this));
        c.setWhite(address(this), true);
        c.setWhite(to, true);

        uint supplyBefore = c.totalSupply();
        uint balToBefore = c.balanceOf(to);
        uint balSelfBefore = c.balanceOf(address(this));
        require(amount <= balSelfBefore);

        // Top-level state-changing call under test.
        c.transfer(to, amount);

        assert(
            c.balanceOf(to) == balToBefore + amount &&
            c.balanceOf(address(this)) == balSelfBefore - amount &&
            c.totalSupply() == supplyBefore
        );
    }

    receive() external payable {}
}

