contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address distributeAddr) public payable {
        require(distributeAddr != address(0));
        require(distributeAddr != address(c));
        require(distributeAddr != c.pairAddress());

        // Configure the caller so it may set the distribute address.
        c.setCaller(address(this));
        c.setDistributeAddress(distributeAddr);

        // The contract must hold enough tokens for the distribution.
        require(c.balanceOf(address(c)) >= 2000 * 1e18);

        uint supplyBefore = c.totalSupply();
        uint balContractBefore = c.balanceOf(address(c));
        uint balDistBefore = c.balanceOf(distributeAddr);

        bool reverted1;
        try c.distributeTokenPeriodic() { reverted1 = false; } catch { reverted1 = true; }

        bool reverted2;
        try c.distributeTokenPeriodic() { reverted2 = false; } catch { reverted2 = true; }

        assert(
            !reverted1 &&
            reverted2 &&
            c.balanceOf(distributeAddr) == balDistBefore + 2000 * 1e18 &&
            c.balanceOf(address(c)) == balContractBefore - 2000 * 1e18 &&
            c.totalSupply() == supplyBefore
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        require(to != c.pairAddress());
        require(amount > 0);
        require(amount <= c.balanceOf(address(this)));

        // The deployer (this contract) holds the initial supply and is whitelisted,
        // so a plain approve + transferFrom must be fee-free and exact.
        c.approve(address(this), amount);

        uint256 supplyBefore = c.totalSupply();
        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(address(this), address(this));

        c.transferFrom(address(this), to, amount);

        assert(
            c.balanceOf(to) == toBefore + amount &&
            c.balanceOf(address(this)) == fromBefore - amount &&
            c.totalSupply() == supplyBefore &&
            allowanceBefore == amount &&
            c.allowance(address(this), address(this)) == 0
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address a) public {
        require(a != address(this));

        bool callerReverted;
        try c.setCaller(a) { callerReverted = false; } catch { callerReverted = true; }

        bool whiteReverted = true;
        bool distReverted = true;
        if (!callerReverted) {
            try c.setWhite(a, true) { whiteReverted = false; } catch { whiteReverted = true; }
            try c.distributeToken() { distReverted = false; } catch { distReverted = true; }
        }

        assert(callerReverted || (whiteReverted && distReverted));
    }

    receive() external payable {}
}
